import React from 'react';
import { FormLabel, Heading, HStack, Input, Stack } from '@chakra-ui/react';

import { labelSettingsInputs } from '../../lib';
import { __ } from '../../lib/i18n';

import type { ICalendarPlusSettings, ChangeHandler } from '../../lib';

interface IFormattingSettingsProps {
	settings: ICalendarPlusSettings;
	handleInputChange: ChangeHandler;
}

export const FormattingSettings: React.FunctionComponent<IFormattingSettingsProps> = ({
	settings,
	handleInputChange,
}) => {
	if (!settings) {
		return <></>;
	}

	return (
		<>
			<Heading mb={6}>{__('Text Labels')}</Heading>
			{Object.keys(labelSettingsInputs).map((label) => (
				<>
					<FormLabel fontWeight={700}>{label}</FormLabel>
					<Stack spacing={4} mb={6}>
						{labelSettingsInputs[label].map(({ id, label }) => (
							<HStack align='center' key={id}>
								<FormLabel htmlFor={id} mb={0} ml={6} minW='300px' fontWeight={400}>
									{label}
								</FormLabel>
								<Input id={id} value={settings[id] ?? ''} onChange={handleInputChange} flex='1' />
							</HStack>
						))}
					</Stack>
				</>
			))}
		</>
	);
};
