import { ChangeEvent, useEffect, useState } from 'react';

import {
	defaultSettings,
	fetchSettings,
	initializeCategoryColors,
	isColorAccessible,
	saveSettings,
	useCustomToast,
	validateDateFormat,
} from '../../lib';
import { __ } from '../../lib/i18n';

import type { CategoryColorType, ICalendarPlusSettings, LayoutAlgorithm } from '../../lib';

export const useCalendarSettings = () => {
	const { showToast } = useCustomToast();
	const [settings, setSettings] = useState<ICalendarPlusSettings | null>(null);
	const [categories, setCategories] = useState<string[]>([]);
	const [formatErrors, setFormatErrors] = useState<{ date?: string; month?: string; time?: string }>({});
	const [loading, setLoading] = useState<boolean>(false);

	useEffect(() => {
		const loadSettings = async () => {
			try {
				const data = await fetchSettings();
				setSettings({ ...defaultSettings, ...data });
				if (window.eventCategories.length > 0) {
					const initialCategories = window.eventCategories;
					const existingColors = data.eventCategoryColors || {};
					const eventCategoryColors = initializeCategoryColors(initialCategories, existingColors);

					setCategories(initialCategories);
					updateSettings({ eventCategoryColors });
				}
			} catch (error) {
				showToast({
					title: __('Error loading settings'),
					description: __('An error occurred while fetching settings.'),
					status: 'error',
				});
			}
		};

		loadSettings();
	}, [showToast]);

	const handleCategoryColor =
		(category: string, type: CategoryColorType) => (event: ChangeEvent<HTMLInputElement>) => {
			const { value } = event.target;

			const newCategoryColors = {
				...settings?.eventCategoryColors,
				[category]: {
					...settings?.eventCategoryColors[category],
					[type]: value,
				},
			};
			updateSettings({ eventCategoryColors: newCategoryColors });
		};

	const updateSettings = (updates: Partial<ICalendarPlusSettings>) => {
		setSettings((prevSettings) => ({ ...prevSettings, ...updates }));
	};

	const validateColors = (settings: ICalendarPlusSettings) => {
		const lightStyles = settings.styles?.light;
		const darkStyles = settings.styles?.dark;

		if (lightStyles) {
			if (!isColorAccessible(lightStyles.calendarBackgroundColor, lightStyles.calendarTextColor)) {
				return __('Light mode calendar background color does not meet contrast requirements with text color.');
			}
			if (!isColorAccessible(lightStyles.calendarToolbarBackgroundColor, lightStyles.calendarTextColor)) {
				return __(
					'Light mode calendar toolbar background color does not meet contrast requirements with text color.'
				);
			}
		}

		if (darkStyles) {
			if (!isColorAccessible(darkStyles.calendarBackgroundColor, darkStyles.calendarTextColor)) {
				return __('Dark mode calendar background color does not meet contrast requirements with text color.');
			}
			if (!isColorAccessible(darkStyles.calendarToolbarBackgroundColor, darkStyles.calendarTextColor)) {
				return __(
					'Dark mode calendar toolbar background color does not meet contrast requirements with text color.'
				);
			}
		}

		return null;
	};

	const handleChange = (view: keyof ICalendarPlusSettings) => {
		setSettings((prevSettings) => {
			const newSettings = { ...prevSettings, [view]: !prevSettings[view] };
			if (newSettings.defaultView === view) {
				newSettings.defaultView = 'month';
			}
			return newSettings;
		});
	};

	const handleSelectChange = (event: ChangeEvent<HTMLSelectElement>) => {
		updateSettings({ defaultView: event.target.value });
	};

	const handleInputChange = (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
		const { id, value } = event.target;
		updateSettings({ [id]: value } as Partial<ICalendarPlusSettings>);
	};

	const handleColorInputChange = (event: ChangeEvent<HTMLInputElement>) => {
		const { id, value } = event.target;
		const mode = id.includes('dark') ? 'dark' : 'light';

		// Extract the color setting id without mode suffix
		const colorId = id.replace(/-(light|dark)$/, '');

		setSettings((prevSettings) => {
			return {
				...prevSettings,
				styles: {
					...prevSettings?.styles,
					[mode]: {
						...prevSettings?.styles?.[mode],
						[colorId]: value,
					},
				},
			};
		});
	};

	const handleFormatChange = (type: 'date' | 'month' | 'time') => (value: string) => {
		updateSettings({
			[`${type}Format`]: value,
			[`custom${type.charAt(0).toUpperCase() + type.slice(1)}Format`]:
				value === 'custom' ? settings?.[`custom${type.charAt(0).toUpperCase() + type.slice(1)}Format`] : '',
		});

		// Clear error if switching from custom to predefined format
		if (value !== 'custom') {
			setFormatErrors((prevErrors) => ({
				...prevErrors,
				[type]: undefined,
			}));
		}
	};

	const handleDateFormatChange = handleFormatChange('date');
	const handleMonthFormatChange = handleFormatChange('month');
	const handleTimeFormatChange = handleFormatChange('time');

	const handleCustomFormatChange =
		(type: 'date' | 'month' | 'time') => (event: React.ChangeEvent<HTMLInputElement>) => {
			const { value } = event.target;

			if (value === '') {
				setFormatErrors((prevErrors) => ({
					...prevErrors,
					[type]: undefined,
				}));
			} else {
				const isValidFormat = validateDateFormat(value);
				setFormatErrors((prevErrors) => ({
					...prevErrors,
					[type]: isValidFormat ? undefined : __('Invalid format'),
				}));
			}

			handleInputChange(event);
		};

	const handleCheckboxChange = (event: React.ChangeEvent<HTMLInputElement>) => {
		const { id, checked } = event.target;
		updateSettings({ [id]: checked } as Partial<ICalendarPlusSettings>);
	};

	const handleLayoutAlgorithmChange = (value: LayoutAlgorithm) => {
		updateSettings({ layoutAlgorithm: value });
	};

	const handleSave = async () => {
		if (!settings) return;
		const error = validateColors(settings);
		if (error) {
			showToast({
				title: 'Error',
				description: error,
				status: 'error',
			});
			return;
		}

		if (Object.values(formatErrors).some((error) => error !== undefined)) {
			showToast({
				title: __('Error'),
				description: __('Please correct the format errors before saving.'),
				status: 'error',
			});
			return;
		}

		try {
			setLoading(true);
			const result = await saveSettings(settings);
			if (result.success) {
				showToast({
					title: __('Settings saved.'),
					description: __('Calendar+ settings are saved.'),
				});
			} else {
				throw new Error(result.message || __('Unknown error'));
			}
			setLoading(false);
		} catch (error) {
			showToast({
				title: __('Error'),
				description: error.message,
				status: 'error',
			});
			setLoading(false);
		}
	};

	return {
		settings,
		categories,
		formatErrors,
		loading,
		handleChange,
		handleSelectChange,
		handleInputChange,
		handleColorInputChange,
		handleDateFormatChange,
		handleMonthFormatChange,
		handleTimeFormatChange,
		handleCustomFormatChange,
		handleCheckboxChange,
		handleLayoutAlgorithmChange,
		handleSave,
		handleCategoryColor,
		updateSettings,
	};
};
