import { ChangeEvent, FunctionComponent, useCallback, useMemo } from 'react';
import { Box, Checkbox, FormControl, FormLabel, Heading, Select, Stack, useDisclosure, Text } from '@chakra-ui/react';

import { ChangeHandler, defaultViewOptions, defaultWeekDayOptions, DEFAULT_WEEK_DAY } from '../../lib';
import { LayoutAlgorithmInstructions } from './instructions';
import { CheckboxInput } from './../../components/ui';
import { __ } from '../../lib/i18n';

import type { ICalendarPlusSettings, LayoutAlgorithm } from '../../lib';

interface IBasicSettingsProps {
	settings: ICalendarPlusSettings;
	handleChange: (view: keyof ICalendarPlusSettings) => void;
	handleInputChange: ChangeHandler;
	handleLayoutAlgorithmChange: (value: LayoutAlgorithm) => void;
}

export const BasicSettings: FunctionComponent<IBasicSettingsProps> = ({
	settings,
	handleChange,
	handleInputChange,
}) => {
	const { isOpen, onClose } = useDisclosure();

	const filteredOptions = defaultViewOptions.filter(
		(option) => settings[`${option.value}View` as keyof ICalendarPlusSettings] ?? false
	);

	const handleCheckboxChange = useCallback(
		(event: ChangeEvent<HTMLInputElement>) => {
			const { id } = event.target;
			handleChange(id as keyof ICalendarPlusSettings);
		},
		[handleChange]
	);

	const filterOptions = useMemo(
		() => [
			{ label: __('Enable Search Option'), id: 'enableSearchFilter' },
			{ label: __('Enable Location Filter'), id: 'enableLocationFilter' },
			{ label: __('Enable Venue Filter'), id: 'enableVenueFilter' },
			{ label: __('Enable Category Filter'), id: 'enableCategoryFilter' },
			{ label: __('Enable Tag Filter'), id: 'enableTagFilter' },
		],
		[]
	);
	return (
		<>
			<Heading mb={4}>{__('Calendar Views')}</Heading>
			<Stack spacing={4}>
				<Checkbox
					id='monthView'
					isChecked={settings.monthView}
					borderRadius='sm'
					onChange={handleCheckboxChange}
				>
					{__('Month View')}
				</Checkbox>
				<Checkbox id='weekView' isChecked={settings.weekView} onChange={handleCheckboxChange}>
					{__('Week View')}
				</Checkbox>
				<Checkbox id='dayView' isChecked={settings.dayView} onChange={handleCheckboxChange}>
					{__('Day View')}
				</Checkbox>
				<Checkbox id='agendaView' isChecked={settings.agendaView} onChange={handleCheckboxChange}>
					{__('Agenda View')}
				</Checkbox>
				<Box pt={8}>
					<FormLabel htmlFor='defaultView'>{__('Default View')}</FormLabel>
					<Select
						id='defaultView'
						value={settings.defaultView ?? 'month'}
						onChange={handleInputChange}
						placeholder={__('Select default view')}
					>
						{filteredOptions.map((option) => (
							<option key={option.value} value={option.value}>
								{option.label}
							</option>
						))}
					</Select>
				</Box>
				<Box pt={1}>
					<FormLabel htmlFor='startOfWeek'>{__('Start of week')}</FormLabel>
					<Select
						id='startOfWeek'
						value={settings.startOfWeek ?? DEFAULT_WEEK_DAY}
						onChange={handleInputChange}
						placeholder={__('Select start day of week')}
					>
						{defaultWeekDayOptions.map((option) => (
							<option key={option.label} value={option.value}>
								{option.label}
							</option>
						))}
					</Select>
				</Box>
				<FormControl pt={5}>
					<Checkbox
						id='enableCalendarFilters'
						isChecked={settings.enableCalendarFilters}
						onChange={handleCheckboxChange}
					>
						{__('Keep sidebar filters visible on Web')}
					</Checkbox>
				</FormControl>
				<FormControl>
					<Checkbox
						id='showFiltersOnTop'
						isChecked={settings.showFiltersOnTop}
						onChange={handleCheckboxChange}
					>
						{__('Show filters on top bar')}
					</Checkbox>
					<Text fontSize='sm' color='gray.500'>
						{__(
							'When enabled, filters will appear below the calendar toolbar, and the sidebar will be hidden.'
						)}
					</Text>
				</FormControl>
				<FormControl>
					<Checkbox
						id='enableFeaturedImage'
						isChecked={settings.enableFeaturedImage}
						onChange={handleCheckboxChange}
					>
						{__('Enable thumbnail/featured image in calendar view')}
					</Checkbox>
					<Text fontSize='sm' color='gray.500'>
						{__(
							'If enabled, the thumbnail/featured image will be displayed on the events in calendar views.'
						)}
					</Text>
				</FormControl>
				<CheckboxInput
					id='showTooltip'
					label={__('Show Event Tooltip/Popover')}
					isChecked={settings?.showTooltip ?? true}
					handleCheckboxChange={handleCheckboxChange}
					helperText={__(
						'If enabled, hovering over an event will not display the tooltip/popover. You can view the event details by clicking on the event instead.'
					)}
				/>
			</Stack>
			<FormLabel htmlFor='defaultView' pt={12}>
				{__('Customize filters')}
			</FormLabel>
			<Stack spacing={4}>
				{filterOptions.map((setting) => (
					<Checkbox
						key={setting.id}
						id={setting.id}
						isChecked={settings[setting.id]}
						onChange={handleCheckboxChange}
					>
						{setting.label}
					</Checkbox>
				))}
			</Stack>
			<LayoutAlgorithmInstructions isOpen={isOpen} onClose={onClose} />
		</>
	);
};
