import React from 'react';
import { Text, Input, Heading, Table, Thead, Tr, Th, Tbody, Td } from '@chakra-ui/react';

import type { CategoryColorChangeHandler, ICalendarPlusSettings } from '../../../lib/types';

interface ICategoryColorSettingsProps {
	categories: string[];
	settings: ICalendarPlusSettings;
	handleCategoryColor: CategoryColorChangeHandler;
}

export const CategoryColorSettings = ({ categories, settings, handleCategoryColor }: ICategoryColorSettingsProps) => {
	if (!settings?.eventCategoryColors) return <></>;

	const { eventCategoryColors } = settings;

	return (
		<>
			<Heading size='md' mb={0} alignSelf='flex-start'>
				Category Colors
			</Heading>
			<Table variant='simple' width='min' alignSelf='flex-start' mt='0px !important'>
				<Thead>
					<Tr>
						<Th minWidth={96} borderBottom='none'>
							Category
						</Th>
						<Th minWidth={48} textAlign='center' borderBottom='none'>
							Background
						</Th>
						<Th minWidth={48} textAlign='center' borderBottom='none'>
							Text
						</Th>
					</Tr>
				</Thead>
				<Tbody>
					{categories.map((category) => (
						<Tr key={category}>
							<Td>
								<Text minW='100px' fontSize='large'>
									{category}
								</Text>
							</Td>
							<Td textAlign='center'>
								<Input
									type='color'
									value={eventCategoryColors[category]?.background}
									onChange={handleCategoryColor(category, 'background')}
									cursor='pointer'
									size='sm'
									width='30px'
									border='none !important'
									p={0}
								/>
							</Td>
							<Td textAlign='center'>
								<Input
									type='color'
									value={eventCategoryColors[category]?.text}
									onChange={handleCategoryColor(category, 'text')}
									cursor='pointer'
									size='sm'
									width='30px'
									border='none !important'
									p={0}
								/>
							</Td>
						</Tr>
					))}
				</Tbody>
			</Table>
		</>
	);
};
