import { format } from 'date-fns';

export const validateDateFormat = (formatString: string) => {
	if (formatString.trim() === '') return true;
	try {
		format(new Date(), formatString);
		return true;
	} catch {
		return false;
	}
};

// Function to calculate luminance of a color
// Luminance is the perceived brightness of a color and is used in contrast calculations
const luminance = (r: number, g: number, b: number): number => {
	// Constants for the color channels' coefficients used in the luminance formula
	const gammaCorrection = (value: number): number => {
		// Normalize RGB values to [0, 1] and apply gamma correction
		const normalizedValue = value / 255;
		// If value is below the threshold, apply a linear correction, else apply a non-linear gamma curve
		return normalizedValue <= 0.03928 ? normalizedValue / 12.92 : Math.pow((normalizedValue + 0.055) / 1.055, 2.4);
	};

	// Apply gamma correction to each color channel (r, g, b)
	const [newR, newG, newB] = [r, g, b].map(gammaCorrection);

	// Luminance formula based on the sRGB color space
	// Coefficients represent the weighted contribution of each color channel to the perceived brightness
	return 0.2126 * newR + 0.7152 * newG + 0.0722 * newB;
};

// Function to calculate contrast ratio between two colors
// Contrast ratio is a ratio of the relative luminances of two colors
const contrastRatio = (color1, color2) => {
	// Convert hex color values (e.g., "#RRGGBB") to RGB values
	const [r1, g1, b1] = color1.match(/\w\w/g).map((x) => parseInt(x, 16));
	const [r2, g2, b2] = color2.match(/\w\w/g).map((x) => parseInt(x, 16));
	// Get luminance of each color using the luminance function
	const L1 = luminance(r1, g1, b1);
	const L2 = luminance(r2, g2, b2);
	// The contrast ratio formula, according to WCAG 2.0 guidelines
	// (Max luminance + 0.05) / (Min luminance + 0.05)
	// The 0.05 is added to avoid division by zero, and it comes from WCAG guidelines.
	return (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05);
};

export const isColorAccessible = (backgroundColor, textColor) => {
	// A contrast ratio of at least 4.5 is required for readability.
	return contrastRatio(backgroundColor, textColor) >= 4.5;
};

export const initializeCategoryColors = (categories, existingColors) => {
	const eventCategoryColors = {};

	categories.forEach((category) => {
		eventCategoryColors[category] = existingColors[category] || { background: '#32C0CD', text: '#ffffff' };
	});
	return eventCategoryColors;
};
